export type Sec = { h: string; p: string };
export const WHATS_NEW: Sec[] = [
  { h: 'A smarter Assistant', p: '•  The Assistant and My Life Live now do sums: add, subtract, times, divide, percent, power and square root, in English or Bahasa Malaysia\n•  New My Life Assistant page in the Home card: tap the glowing orb and the talking Assistant opens straight away. It is the first page each time you open the app. Turn it off in Settings, Dashboard card\n•  The AI on your phone is now given a short summary of your own saved data (spending, commitments, goals, habits, tasks, events), so it can answer questions about you in its own words and with your real numbers\n•  That summary never goes to Online AI. Only the AI downloaded on your phone sees it' },
  { h: 'Small touches', p: '•  What you owe: sort it, and tap a commitment to see how much is left, the monthly amount and roughly when it ends\n•  Spending categories: add your own or delete any category except Other from the Add spending chips (move its spending to Other or delete it too), and set a monthly limit in Spending by Category\n•  Experiments: press OK when one is done and it goes to History. Run again, Share, add notes, set an 8:30 pm reminder or choose your own target number. Past ones sit behind a History button\n•  What you owe and Money you have now have their own sort buttons\n•  Boxes with three choices, such as deleting a category, now stack the buttons so the words fit\n•  Energy estimate: clearer wording of what it was worked out from, and your night pulse from the Heart log (including Health Connect) now counts a little when it is clearly lower or higher than your usual\n•  New badges in Your Memories for finished experiments\n•  My Life Live: a cleaner start with no list of sample phrases, a modern glass look, it greets you and says you can ask about your data, and long answers scroll along with the voice inside their own card\n•  My Accounts: sort groups by most money, least money or A to Z, or move them yourself; every transfer has a reference on both accounts, and tap a line for bank-style details\n•  Transfers show a smoother animation with the sound of coins dropping into a money box\n•  Spending history is shown one month at a time with a month picker (6 items first, Show all for the rest)\n•  Photos from your gallery (Scans, Documents, Subscriptions bills, receipts) can go through the scanner to crop and add a filter, and the Save sheet shows the real size of your photo\n•  The Assistant button that opens My Life Live has a wave icon, so it is not mistaken for typing by voice' },
  { h: 'Goals and limits', p: '•  A savings goal can now say which of your accounts the money is kept in\n•  Empty or wrong target weight and category limit boxes now show a message, and there is a Remove button to clear them' },
  { h: 'Spending from a sentence', p: '•  Tell the Assistant a normal sentence like "makan tengah hari 12 guna Maybank" and the AI on your phone reads it\n•  It picks the category and the account for you, and you tap to confirm before it is saved' },
  { h: 'Scan to PDF', p: '•  New Scans part in Documents, kept apart from your papers\n•  Scan many pages at once, pick Auto clean, Colour, Grey or Black and white, and choose sharp 2K quality\n•  Turn, reorder or delete pages, then make one PDF to share' },
  { h: 'My Life Live', p: '•  New live voice screen: a moving wave while you talk and while it answers\n•  It greets you by name, then chat about anything. Pick a male or female sound, speed and how long it waits\n•  Talk in Chinese, Tamil, Arabic and 20 more languages with a language pack (about 30 MB)' },
  { h: 'Reminders on time', p: '•  Settings, Notifications has a new button that opens your phone\'s battery setting, so reminders are not stopped or late' },
  { h: 'More in Stats and Insights', p: '•  Stats, Money: your total money and your subscriptions each month and year\n•  Stats, Health: your pulse this week\n•  Insights now tells you when an account is below zero, a subscription or trial is about to charge, or your pulse stays high' },
  { h: 'Calmer heart log', p: '•  The watch now adds one pulse reading every 6 hours, so the notebook stays short and tidy\n•  The photo cut-out tells you to tap CROP at the top right to finish' },
  { h: 'Your own logos', p: '•  In Subscriptions and My Accounts, choose a picture from your gallery and cut out the square you want, and it becomes the logo\n•  It is made small on your phone and stays there. It is not saved to your account' },
  { h: 'Better document scans', p: '•  Scan with camera now works like a scanner app: it finds the paper, straightens and crops it, and clears up the colours\n•  Used in Documents and for bills in Subscriptions\n•  It all happens on your phone and nothing is uploaded' },
  { h: 'Smoother buttons, tabs and warnings', p: '•  Buttons shrink a little when pressed, and the phone taps only for the important ones, such as Save\n•  Tabs in Settings, Stats, Fasting and Activities now slide\n•  Boxes tell you what is missing or wrong and shake\n•  Currency now follows your country everywhere' },
  { h: 'My Accounts', p: '•  New card in My Finance: add your cash, banks, wallets, savings and cards, and see your total money\n•  Spending, Commitments and Income can come off or go into an account\n•  Transfer, add money, or set a balance to match your bank\n•  Worked out on your phone. My Life 1.0 never connects to your bank' },
  { h: 'Energy', p: '•  New Energy card in Habit and Health: a score, a short tip and a week or month trend\n•  Tap how you feel, or let My Life 1.0 estimate it\n•  The Dashboard Quick log asks after your mood\n•  Your pulse while you sleep helps the estimate' },
  { h: 'Heart log', p: '•  Type your own pulse and blood pressure in Habit and Health, Today tab\n•  Turn on Pulse from my smart watch to bring in your heart rate through Health Connect (Samsung Health, Honor Health, Mi Fitness, Fitbit and more)\n•  It is your own notes, not medical advice' },
  { h: 'Part payments and a PDF of your things', p: '•  Lent & Borrowed: when someone pays back only part of the money, tap Add a payment. It shows how much is paid back and how much is still owed, and the record moves to Done by itself when it is all paid\n•  Personal Collection has a new button, My things as a PDF: a list of everything you own with price, date, warranty, worth and a photo, handy for an insurance claim. It is made on your phone and nothing is uploaded\n•  Backups can now hold up to 80 photos' },
  { h: 'Personal Collection: worth, warranty and photos', p: '•  Gadgets show what you paid and what each one is worth now. You can type the number yourself and pick its condition (Like new, Good, Worn or Broken). If you leave it empty, My Life 1.0 makes a guess on your phone from the price, how old it is, the kind of gadget, the brand and the condition. A guess is not a market price, and it is not shown for Lifestyle or Property\n•  Each gadget shows how many days of warranty are left, with a bar, and a reminder 30 days before it ends\n•  Link a receipt or warranty paper from Documents to an item and open it from there\n•  Lent & Borrowed can remind you on the due date or 3 days before, shows your history with each person, and can open WhatsApp, or any other messaging app you pick, with a polite message that you send yourself. My Life 1.0 sends nothing for you\n•  Up to 5 photos for each item, longer notes (500 letters), and a List or Grid view that is remembered for each section. Photos stay on your phone' },
  { h: 'Documents: renewing, lock and sharing', p: '•  A Renewing soon card at the top of Documents shows the papers that end first, across all tabs\n•  Every paper has How to renew: step by step help, what to bring and a link to the official page. It says where the steps came from. My Life 1.0 cannot renew anything for you\n•  You can lock Documents with your fingerprint, face or phone lock. It is your choice and it stays on this phone\n•  Copy a number or name with one tap. The copy is cleared from the clipboard after a minute\n•  Share a picture of a paper with a bar across it that says why you are sharing it, such as For hotel booking only. You can turn the bar off if you do not want it. It is made on your phone and nothing is uploaded\n•  A paper can now have several pages, and you can export them as one PDF. The pictures stay on your phone only\n•  Passports, bank cards, permits and other IDs now have an Issued in choice: Malaysia or Another country. How to renew shows steps that fit the country you pick. Only that choice is saved, like the rest of the details' },
  { h: 'Subscriptions in My Finance', p: '•  A new Subscriptions card sits under Savings Goals in My Finance. It shows what you pay every month for Netflix, YouTube, Spotify and the like, and when each one charges next\n•  My Life 1.0 looks through your own spending and suggests payments that repeat every month. You choose to add them or hide them\n•  You can also pick a service from a list, or scan a bill or receipt. The text is read on your phone\n•  Free trials show a warning before they end, and you can get a reminder before each charge\n•  What you pay on subscriptions is taken off your Money Left\n•  Each subscription shows its first letters in a colour, or your own image if you pick one\n•  Subscription details are saved to your account like your other data. The images you pick stay on the phone only\n•  Phone and internet plans are left out of Subscriptions, because they are already a monthly commitment in Money Left\n•  The Dashboard calendar pages now show public holidays and Islamic dates only. Your own events stay on the Next event page\n•  Subscriptions now use the currency you chose in Settings. When you scan a receipt in a different currency, My Life 1.0 tells you to type the price in your own currency. Nothing is converted\n•  Subscriptions can now be Active, Paused or Cancelled. Paused and cancelled ones stay in your list but are left out of your totals, reminders and Money Left\n•  New ways to repeat: every 3 months and every 6 months\n•  You can note how you pay for each one (debit card, credit card, e-wallet, bank). Only the type is kept, never a card number\n•  All on/off switches in the app now slide with a small animation and give a short vibration when you flip them\n•  Subscriptions now has How to cancel. Open a subscription and tap it for step by step help to stop paying for Netflix, YouTube, Spotify and more, with a link to the official page of the service. My Life 1.0 cannot cancel for you. When you are done, tap the button to mark it as cancelled\n•  The days left before each charge are now shown on the Upcoming renewal card and in your list\n•  Tabs in Family and Quran Audio now glide to the one you tap, with a short vibration\n•  When a subscription charge day comes, My Finance asks if it was charged. Tap Add to my spending and it goes into Money Left, Today\'s spending and Spending by category, saved under Bills. Tap Not this time to skip it\n•  The Summary on Subscriptions is now one card that turns by itself every few seconds, like the card on the Dashboard. A thin bar at the bottom for each page fills up before the card turns. Press and hold to pause it, or swipe left or right to turn it yourself. The pages are Costliest (your subscriptions from the most expensive, with the cost a year), Per day (what they cost every day, and what share of your income this month), By payment (how much leaves each debit card, credit card, e-wallet or bank), Save (the three that would free up the most money a year, with a way to open each one) and Next 5 months. Everything is worked out on your phone from what you already saved' },
  { h: 'Documents and Personal Collection now come back on a new phone', p: '•  The details you type in Documents and Personal Collection (names, numbers, dates, prices, notes, who you lent to or borrowed from, life lessons) are now saved to your account like your other data. Sign in on a new phone and they come back\n•  Photos are not saved online. They stay on the phone you took them on, so your online storage does not fill up. Keep a Backup (JSON) file from Settings, Export to move the photos to a new phone\n•  The note at the top of each form now says this clearly: details sync, photos stay on this phone\n•  The Documents and Personal Collection pages have slow, gentle moving art, and the icons are now thin line icons instead of emoji\n•  The Dashboard card has a new look with yellow for close to due and red for overdue, and two new pages, Upcoming calendar (all) and Upcoming calendar (general)' },
  { h: 'New look and two calendar pages for the Dashboard card', p: '•  The card at the bottom of the Dashboard has a new look: a soft glow in each page\'s colour, a faded picture in the corner and a small status tag. All pages now use the same sizes so the text is easier to read\n•  Yellow means something is close to its date, red means it is overdue\n•  Two new pages: Upcoming calendar (all) shows your own events, public holidays and Islamic dates, nearest first, and Upcoming calendar (general) shows your events and public holidays only. Switch either one off in Settings, General, Dashboard card\n•  Road tax, insurance and licence now turn yellow within 30 days and red only once they have expired' },
  { h: 'A new life lesson every day', p: '•  The card at the bottom of the Dashboard has a new page, Life lesson. It shows a short lesson about money, people, work, time, health or yourself, and it changes every day\n•  There are over 100 built-in lessons, and every third day it shows one that you wrote yourself in Personal Collection, Life Lessons\n•  Tap the page to open Life Lessons. You can turn this page off in Settings, Dashboard card\n•  Life Lessons now opens its add box properly when you tap the plus button' },
  { h: 'Documents and Personal Collection, finished', p: '•  Export and Backup now include Documents and Personal Collection, with their photos. Choose them in Export my data, and turn them off if you do not want them in the file\n•  The Assistant can answer which document ends soon and who owes you money or a thing\n•  Add document now shows only the types that belong to the tab you are in, and fills the full width\n•  Personal Collection has new fine art in the Documents colours, and the icons on its home page glow slowly\n•  Tabs slide and fade when you switch them in Daily Planner, Islamic Hub, Medicine, Relax, Hafazan, Habit & Health, Documents and Lent & Borrowed\n•  Dashboard card tips and titles are no longer cut short, and the card keeps turning after you come back from a page\n•  Fixed the Personal Collection home page so the cards sit two in a row on every phone, and the badge icons in Your Memories sit in the middle of their circles' },
  { h: 'Version 1.0.1', p: 'Family Planner, AI in the Assistant, more countries and currencies, and a calmer Settings.' },
  { h: 'AI in the Assistant', p: '•  Ask anything your data cannot answer. Turn on AI in Settings, Language and AI\n•  Online AI is the smartest. It needs internet and sign-in, has a daily limit, and is off until you turn it on\n•  Smart chat runs on your phone with no internet: Smart chat (550 MB), Smart chat+ (1.6 GB), or Max on phones with 12 GB of memory or more (Gemma 4 or Qwen 3.5, which we recommend)\n•  A small label under each AI answer shows where it came from\n•  Downloads are faster and can be resumed' },
  { h: 'Chat like a friend', p: '•  The AI answers questions, explains step by step, writes and fixes code, gives its opinion and remembers the last few messages\n•  Paste a long text and ask for a summary in points\n•  Answers appear softly, word by word, with bullets, bold words and code boxes' },
  { h: 'Chat in your language', p: 'Chat in more than 20 languages. Pick one in Language and AI. The language pack downloads once, and translation stays on your phone.' },
  { h: 'Family Planner', p: '•  Share tasks, activities and a shopping list with your family\n•  Repeating tasks and reminders for everyone\n•  Deleted items can be brought back for 7 days\n•  The owner can turn the invite code on or off, or delete the family\n•  Also available as a Dashboard module (Settings, Modules)' },
  { h: 'Quran Audio', p: '•  In the Islamic Hub, open the Quran tab and tap Quran Audio\n•  Pick a reciter, then play any of the 30 juz or 114 surahs, verse by verse with its translation, even when the screen is off\n•  Streams by default. Download a surah or juz to listen offline, on Wi-Fi only or also mobile data\n•  Search, Continue where you stopped, and see what is saved in Downloads' },
  { h: 'Safer deleting and nicer search', p: '•  Before anything is deleted or removed, such as a task, a note, a reading, a bookmark or an unpinned note, the app now asks Are you sure so a wrong tap does not lose anything\n•  Every search box now glows and shines like the one in Quran Audio\n•  Insights now tells you when a maintenance job or part is late or due soon\n•  The vehicle score ring has a softer, animated look' },
  { h: 'Vehicle score in My Record', p: '•  One card named after your vehicle, for example Motorcycle score: a health score, then road tax, insurance and licence dates, then jobs you repeat such as spraying the chain or checking tyre pressure\n•  See how many days since you last did it and how many days are left. Add a km limit too, and the job is due at whichever comes first\n•  Tap Done today, with a cost if you like, and the cost goes into Spending\n•  Parts you replace, such as tyres, battery and brake pads, now sit in the same list as Replace items, with km or days. Parts you saved before moved over by themselves, and your health score counts everything once\n•  Km are optional. With a few odometer readings the app estimates your odometer from your average daily distance, shows it as an estimate, and you can correct it any time, or type it when you tap Done\n•  A 9 am reminder with a Done button, and a vehicle health score that counts tasks, parts and renewals' },
  { h: 'Week starts on your day', p: 'Weekly charts in Habit and Health, the dashboard streak, Insights, Stats, Relax, Medicine and the Islamic Hub week now show this week, so last week no longer mixes in. In Settings, under Region, choose Week starts on: Auto (follows your country), Mon, Sun or Sat.' },
  { h: 'Checks on what you type', p: '•  Every number box now checks what you type. A wrong entry, such as 12.3.4, a negative number or a figure that is far too big, gets a red edge and a short reason under the box. The box also shakes a little and your phone gives a short buzz. Time boxes (sleep, medicine, Relax reminder) do the same when the time is not real\n•  A wrong number is not saved until you fix it\n•  If you press Add or Save while a needed number is empty or zero, the box tells you what to type, for example Please enter an amount\n•  Pulse, blood pressure, weight, height, age, steps, odometer and the due day of a month each have a sensible range' },
  { h: 'More pages on the Dashboard card', p: '•  The card at the bottom of the Dashboard now turns by itself every 5 seconds. Tap it to turn it yourself\n•  New pages: Next prayer, Next event with days left, a Vehicle job that is due soon or late, and Money this month\n•  A page only appears when there is something to show, so you never see an empty one\n•  App Usage was removed from this card' },
  { h: 'Your Memories with My Life 1.0', p: '•  Every moment matters. Every journey tells a story. Open it from the Quick log card on the Dashboard, which turns by itself, or from Settings, About\n•  Our Journey Together: how many days you have been with My Life 1.0, with 30 day, 100 day and 1 year milestones\n•  Your Life in Numbers: notes, finished tasks, achieved plans, tracked health days and saved records\n•  Your Timeline and On This Day: moments from your own notes, tasks, plans and vehicle care, and what happened on this date before\n•  Your Achievements: badges that open only when you really meet them\n•  Your Year in Review: your busiest months and highlights\n•  You are in control: hide any memory, turn off the Dashboard card, or reset your memories. Your notes, tasks and records are never deleted by this' },
  { h: 'Personal Collection', p: '•  Gadgets, Lifestyle and Property: save what you own with a kind, a photo, the price and the date you bought it. Gadgets also track the warranty and remind you 30 days before it ends\n•  Lent & Borrowed: write down money or things you lent or borrowed, with a due date. See who owes you, mark things as returned, and get a 9 am reminder on the due date\n•  Life Lessons: keep short notes about what you learned, with a tag and a date\n•  Every part has search, and you add things from inside each part When you tap WhatsApp or Other apps on a loan, the message text is handed to that app on your phone and you choose who gets it and press send yourself. Links to papers in Documents stay on your phone and in your account like the rest of your details.' },
  { h: 'Documents in My Record', p: '•  Keep your important papers in four tabs: Identity (passport, MyKad, CIDB, permits), Cards (bank and member cards), Warranty and Other (insurance, agreements, certificates)\n•  Scan a document with the camera or choose a photo, and My Life 1.0 reads the words on your phone to fill in the name, number and expiry date. A passport is read from its two lines at the bottom. My Life 1.0 also guesses the kind of document, such as passport, MyKad or bank card, and you can change it. For a bank card only the last 4 digits are kept. Always check what it filled in\n•  Keep a photo of each document. Tap a document, for example your CIMB card, to see its photo, number, expiry and reminder on one page, and open the photo full screen. The number is optional\n•  Pick a reminder for each document: none, 1 week, 1 month, 3 months or 6 months before it expires, plus one on the day\n•  A ring shows how long is left, and papers close to expiring turn red' },
  { h: 'My Record is now a hub', p: '•  Opening My Record now shows three parts: Documents, My Vehicle and Personal Collection\n•  Everything you had before, including mileage, fuel, maintenance tasks and renewals, is now inside My Vehicle and nothing was removed\n•  Personal Collection is now ready too, see the next item' },
  { h: 'A new look for the Dashboard card', p: '•  Every page now has an icon tile, a clear title and a progress ring, such as days left for an event or how much money is left\n•  A thin bar at the bottom shows which page you are on. Tap a part of the bar to jump to that page\n•  Tap the card to open that page. Press and hold to see the next page. Quick log keeps its own buttons\n•  The card glows red when something is late or due very soon' },
  { h: 'Three more Dashboard card pages', p: '•  Tasks today: tasks due today and any that are late\n•  Road tax, insurance, licence: shows when one expires within 30 days, or expired in the last 60 days\n•  Debt payment: a payment due within 7 days, or this month\'s payment that is late\n•  Each page appears only when there is something to show, and you can switch any of them off in Settings, Dashboard card' },
  { h: 'Choose your Dashboard card pages', p: '•  In Settings, General, tap Dashboard card to open its own screen, then switch off any page you do not want in the card at the bottom of Home, such as Next prayer, Money this month or Tip. Quick log is always shown\n•  The Next prayer page no longer asks for your location by itself. It only uses a location you already allowed in the Islamic Hub\n•  The notification permission popup no longer shows over the login screen or on Home by itself. It appears when you open a module that uses reminders, or when you press something that needs notifications, such as Going to sleep or Set reminder\n•  The progress line in Your Memories now has three parts, one for each milestone, so 12 days no longer looks half way to 100 days' },
  { h: 'Closer odometer estimate', p: '•  The Odometer now (estimate) in Maintenance tasks now uses how far you rode in the last few weeks, not your whole history, so an old busy period no longer pushes it too high\n•  Days you do not ride are already counted in the daily average\n•  The card tells you which days the guess is based on. Type a new reading any time to make it exact\n•  The real reading you type on that card always updates the estimate. Tap Monthly Mileage or Yearly Mileage under the box only when you also want it to count there, so weekly updates do not fill those lists. A second reading on the same day replaces the first\n•  The odometer you type in the Fuel log counts for the estimate too. When the newest number is one you typed, the card says Odometer now (actual) and shows its date; it says estimate only when it is a guess' },
  { h: 'Event days left', p: '•  Each event in Date and Events now shows how many days are left: red when it is overdue, yellow when it is a week or less away, green when there is still time\n•  Sleep Schedule for the last 30 days no longer opens with a long block of empty days\n•  In the Sleep Tracker, a bed or wake time that is not a real time, or a sleep longer than 24 hours, is not accepted and the app tells you why' },
  { h: 'Sleep timer', p: '•  On the Dashboard, the Quick log says You have not slept yet. Tap Going to sleep when you go to bed, or Add to Quick Settings to start it from the pull-down panel of your phone\n•  The notification button I\'m awake and the Quick Settings tile work without opening the app. The hours are saved in the Sleep Tracker the next time you open it\n•  If you slept less than 6 hours or more than 9, you get a gentle warning\n•  A quiet notification shows Sleeping since. Tap I\'m awake when you wake up and your hours are saved for you\n•  On Android you can add a Going to sleep tile to Quick Settings, so one tap from the top of the screen starts or ends it\n•  You can still type your sleep by hand' },
  { h: 'Hafazan Check', p: '•  In the Islamic Hub, Quran tab, tap Hafazan Check. Recite and see which words you said and which you skipped\n•  Learn: listen to a verse, then recite it back. Test: recite from memory with the verse hidden. Find: just start reciting and the app finds the surah and verse\n•  Tap a coloured word to see what went wrong and hear the verse again\n•  Listening runs on your phone. Your voice is never uploaded. The Quran model (about 57 MB) is downloaded once and can be removed any time\n•  It checks words, not tajwid or madd' },
  { h: 'Islamic Hub Today', p: '•  A card that changes every 10 seconds: Your week, the next Islamic event (Awal Muharram, Asyura, Maulidur Rasul, Ramadan, Eid and more), a verse for the day and Continue reading\n•  Your week shows seven days of Quran, zikir and fasting, your streak and the tasbih count of the day\n•  The verse fits the day: an Islamic event, Ramadan, Friday, or a short verse that changes daily\n•  Swipe the card to change it, or press and hold to pause. Tap the event card to see the next events\n•  Dates follow JAKIM when you are online and are estimates, because the final date depends on the moon sighting' },
  { h: 'Quran text', p: 'Cleaner Arabic text in the reader: fixed tanwin spacing and stray marks, so every verse reads like the printed mushaf.' },
  { h: 'Medicine', p: '•  Reminders ring like an alarm clock so your phone does not hold them back (turn off with Never late)\n•  A dose not ticked an hour after its time is marked Missed. Today and the Week tab show them\n•  Insights shows a tip when you missed doses in the last 7 days\n•  Edit a saved medicine, including its time, days and icon\n•  Add medicines with dose, time and repeat days, and tick them off each day' },
  { h: 'Insights and Stats', p: '•  Relax and Medicine now count toward your Life Score, plus Budget left\n•  The weekly review compares relax, energy and medicine with last week\n•  New tips for medicine, relax, low energy and Cycle\n•  Patterns link your energy and relax sessions to your sleep and mood\n•  Stats has Relax, Energy and Medicine in the 7-day charts, new cards and relax records' },
  { h: 'Spending and Finance', p: '•  Today\'s spending lists each item with its note\n•  Sort spending, add a remark and edit an entry\n•  Maintenance from My Record can count as a Vehicle category in My Finance. My Life 1.0 asks first, and you can switch it any time\n•  It also shows in Stats, Insights, budget alerts and exports' },
  { h: 'Notes and reminders', p: '•  Notes in the Daily Planner can have a reminder: in 1 hour, tonight, tomorrow morning or any date and time\n•  Add extra alerts before it, from 5 minutes up to 1 day\n•  Notes with a reminder show a bell, and the Reminders bar lists them soonest first\n•  Quick reminder: tap the search button on the Dashboard and choose Remind me, or ask the Assistant: "remind me tomorrow 12pm to charge laptop"\n•  Reminders ring like a normal notification, and stay quiet on silent or Do Not Disturb' },
  { h: 'A smarter Assistant', p: '•  Ask about your pulse, blood pressure, medicines, Relax minutes and experiment\n•  Say "pulse 72" or "add milk and eggs to my shopping list" to save it\n•  Undo what it just saved, and get a short brief of your day\n•  Suggestions change with your day, and on Sunday it shows a look back at your week' },
  { h: 'Habit and Health', p: '•  New first tab, Patterns: your day at a glance, an energy estimate, patterns from your own records, and a Time Machine\n•  Body hologram (flat or 3D): tap a body part, go back to any day, compare two days, or see an estimate ahead\n•  Experiments: try a 7 or 14 day challenge and see before and after\n•  Relax: breathing exercises, a meditation timer and an optional daily reminder\n•  Cycle tracking, off by default. Turn it on in Settings\n•  Steps count all day from your phone\'s step sensor\n•  The Dashboard card asks for the next thing you have not logged today: sleep, mood, medicine and water' },
  { h: 'Region and currency', p: 'Public holidays, currency symbols and money words follow the country you choose. New: Cambodia, Laos, Myanmar, United Kingdom, United States, Maldives, Taiwan, Kuwait, Bahrain, New Zealand and Germany.' },
  { h: 'Islamic Hub', p: '•  Prayer times, daily zikir and alert timing moved into the Islamic Hub (tap the gear icon)\n•  Read Quran, Tahlil, Mathurat and dhikr with translation, Arabic only, or continuous\n•  Reminders for Road tax, Insurance and Driving licence: 30 days, 7 days and on the day' },
  { h: 'Dashboard and backup', p: 'Tap the bottom Dashboard card to switch views, and reorder Dashboard cards. Backups now include My Record receipt photos. A module you turn off no longer shows its links elsewhere, and starts unticked in Export.' },
  { h: 'New logo', p: 'The logo inside the app now matches your home screen icon, with a soft glass look and gentle moving lights.' },
  { h: 'Fixes', p: '•  Sleep tracker times type and clear properly\n•  Budget alerts show while the app is open\n•  Reminder settings sync between your devices\n•  Clearer steps to connect Honor Health or Samsung Health' },
  { h: 'Version 1.0.0', p: 'The first release of My Life 1.0: planner, prayer times and Quran, finance, vehicle records, habits and health, Family Planner, Assistant, Stats and Insights, in one calm app with no ads. Your data lives encrypted on your phone, with an optional PIN or fingerprint lock and a private backup to your own account. Export to Excel, PDF or CSV any time.' },
];
export const PRIVACY: Sec[] = [
  { h: 'What we store', p: 'Your account (name, email and a password that we only keep in scrambled form), and what you enter yourself: notes, events, finance entries, records and habits. Stats about how long you use the app are kept on your device for 30 days. For security and to protect licences, the app owner can see how many devices are signed in to each account and when the account was last active. This does not include your notes, finances or other personal data. The app itself does not store IP addresses or device names, but the sign-in service we use (Supabase) may keep technical records, such as an IP address, for security.' },
  { h: 'Where it lives', p: 'Your data lives first on your phone, encrypted there. When you are signed in, a copy is also saved to your account on our server (Supabase, hosted in Singapore) so you can use it on other phones and get it back if you lose this one. Each account can only read its own data, plus the shared Family Planner space of the family it belongs to. Receipt photos stay on the phone and are not uploaded. Your subscription list (names, prices, dates) and your accounts in My Finance are saved to your account too, but the logo images you pick stay on the phone only. When you scan a bill, the text is read on your phone and the picture is not kept; only if you tap Read with AI is that text, never the picture, sent to the online assistant. The details you type in Documents and Personal Collection are saved to your account like your other data, but their photos stay on the phone only. The one exception is a private photo backup that is switched on for a single account by the app\'s owner: those photos are kept in a private storage folder that only that account can open.' },
  { h: 'Family Planner', p: 'If you use Family Planner, what you add there is saved on our server in a space shared by your family: the family name, members\' names and colours, birthdays you add, tasks, chores and reward points, the shopping list, menu, wishes and activities. Every member can see and change it. This is the one place where data is shared between accounts, and only people who joined with your family code can see it. The owner can add profiles for people without an account, such as children; we only keep a name, a colour and, if you add it, a birthday for them. Deleted items stay in Recently deleted for 7 days. Anyone can leave a family. The owner can remove members or delete the family, which deletes everything in it. If the owner deletes their account, the family and its data are deleted too.' },
  { h: 'What we never do', p: 'We do not show ads, track you across other apps or sell your data. We only send data to the services the app needs in order to work, listed under Other services, and only what each one needs. The server stores your data so the app can sync it; it is not end-to-end encrypted, so the developer could technically access it, but does not read it.' },
  { h: 'Location', p: 'Prayer times use your location only to work out the times. Your coordinates are sent to the prayer-time service (waktusolat.app) to look up your zone. The last place found is kept on your phone only, so times can show without asking again, and it is not saved to your account. You can choose your zone by hand instead.' },
  { h: 'Steps and health', p: 'If you allow it, My Life 1.0 reads your step count from your phone\'s step sensor or Health Connect to fill in your daily goal. Steps are kept with your habit data: saved on your phone and, when you are signed in, in your online copy. They are not used for anything else. If you turn on Pulse from my smart watch in the Heart log, My Life 1.0 also reads your heart rate from Health Connect (only after you allow it). Your phone shares nothing with My Life 1.0 until you do, and My Life 1.0 never talks to the watch itself. One reading every 6 hours is added to your Heart log and kept like your other habit data. For the night, the lowest reading is kept, and My Life 1.0 compares it with your own usual night pulse to improve the Energy estimate. You can turn it off, delete any reading, and take away the permission in Health Connect at any time. It is a guide only, not medical advice.' },
  { h: 'Medicine reminders', p: 'If you add medicines in Habit and Health, the names, doses and times you type, and what you tick as taken, are kept with your habit data: encrypted on your phone and, when you are signed in, in your online copy. They are used only to remind you and to show which doses you missed, worked out on your phone. My Life 1.0 does not give medical or dose advice. Relax sessions (which exercise, how long and when) are kept in the same way. If you turn on Cycle tracking, the days you mark as a period and the symptoms you tick are kept in the same way. They are used only to show your own record and estimates, never for advertising, and My Life 1.0 does not give medical advice. If you log your pulse or blood pressure, the numbers you type are kept in the same way and used only to show your own record. My Life 1.0 does not measure them, judge them or give medical advice. The reminder shows the medicine name on your lock screen, so turn Medicine reminders off in Settings if you prefer.' },
  { h: 'Quran Audio', p: 'Recitations you download are saved only on your phone, in the app\'s own storage, and you can delete them any time in Quran Audio, Downloads. They are not uploaded and not part of your online copy. The reciter you picked, the Wi-Fi setting and the place where you stopped listening are also kept on your phone only. Removing the app removes them.' },
  { h: 'Personal Collection', p: 'The things you add in Personal Collection, such as names, prices, dates, notes, who you lent to or borrowed from, and your life lessons, are saved on your phone and in your account backup like your other data. Photos are kept on your phone only and are never uploaded. Reminders are made on your phone. If you save a backup file or an export from Settings, what you choose goes into that file, which stays with you.' },
  { h: 'Documents and scanning', p: 'The documents you add in My Record, such as names, numbers and expiry dates, are saved on your phone and in your account backup like your other data. The photos are kept on your phone only and are never uploaded. When you tap Scan with camera, My Life 1.0 asks for camera permission only then. The page is found, straightened and cleaned up on your phone by the Google document scanner, which is part of Google Play services on your phone. The words in the photo are read on your phone by the phone itself, and the photo is not sent anywhere. If you save a backup file or an export from Settings, the documents you choose go into that file, which stays with you. Reminders are made on your phone.' },
  { h: 'Spending from a sentence', p: 'When you write a spending in your own words and the Assistant does not understand it with its normal rules, the AI model on your phone (if you downloaded one) reads the sentence and fills in the amount, category and account. This happens only on your phone: the sentence is not sent to the internet and not to Online AI. Nothing is saved until you tap to confirm. The account link is saved with the spending in My Finance and syncs like your other spending.' },
  { h: 'Scans in Documents', p: 'The Scans part of Documents lets you scan papers into a PDF. The pages are found, straightened and cleaned on your phone by the Google document scanner, which is part of Google Play services, and the filters you choose are applied there. Camera permission is asked only when you tap Scan pages. The scanned pages and their names stay on your phone only: they are not synced, not uploaded and not in your account backup. The PDF is made on your phone and only you decide where to share it.' },
  { h: 'Maintenance tasks', p: 'The tasks you add in My Record, their dates, km limits and any cost you type are kept on your phone and in your account backup like your other vehicle records. Reminders are made on your phone and nothing extra is sent anywhere.' },
  { h: 'Your Memories', p: 'Your Memories with My Life 1.0 is worked out on your phone from data you already saved, such as notes, tasks, plans, health logs and records. The only extra things saved are the memories you chose to hide, the date each badge was first unlocked, and whether the Dashboard card is on. They are backed up with your other data and are removed when you reset your data or delete your account. Nothing is shared with other people.' },
  { h: 'Sleep timer', p: 'When you tap Going to sleep, the start time is kept on your phone and a notification is shown. When you tap I\'m awake, the hours are saved in your Habit and Health data like any other entry. Nothing is sent anywhere else.' },
  { h: 'Experiments', p: 'Your experiments, the notes you write in them and their History are kept with your Habit and Health data: encrypted on your phone and, when you are signed in, in your online copy. The optional 8:30 pm reminder is a notification scheduled on your phone. Nothing is shared unless you tap Share, which only sends the short summary you choose to send.' },
  { h: 'My Life Live (talking to the Assistant)', p: 'The microphone button in the Assistant listens only after you tap it and allow the microphone, and it stops when you stop talking or close the voice screen. Your voice is turned into text by the speech recognition service of your phone (on most Android phones this is Google\'s speech service, which may send the audio to its servers unless an offline language is installed on the phone). My Life 1.0 does not record or keep your voice and does not send it to our server. The words are then handled like anything you type to the Assistant. The Assistant reads its answers aloud with your phone\'s own voice. When you chat by voice, the AI on your phone answers first if it is downloaded. If you turned on Online AI and the AI on your phone is not ready, your words and your last few messages are sent over the internet to get the answer. When you talk in another language, your words are translated on your phone with the language pack, and the answer is translated back. The language packs are downloaded once from Google. Your chosen language, voice, tone and speed are kept only on your phone.' },
  { h: 'Assistant and your own data', p: 'To answer questions about you, the AI downloaded on your phone is given a short written summary of your saved data (such as this month\'s spending, commitments, goals, habits, tasks and events). It is made on your phone each time, used only for that answer and not saved anywhere else. It is never sent to Online AI: Online AI only receives the question you type or say, plus your last few messages in a voice chat. Sums are worked out on your phone without any AI.' },
  { h: 'Hafazan Check', p: 'Hafazan Check uses the microphone only while you recite, after you allow it. Your voice is turned into text on your phone by a Quran model that runs there. The audio is not recorded to a file, not uploaded and not sent to any server, and the app works with the result as text only. The model (about 57 MB) is downloaded once from GitHub, and you can delete it in Hafazan Check. Your chosen surah, verses and settings are kept on your phone only.' },
  { h: 'Islamic Hub activity', p: 'Which days you opened a surah or zikir, shown in Your week, is kept on your phone only and is not part of your online copy. It keeps the last 45 days. The Hijri date is read from JAKIM (e-solat.gov.my) when you are online, with no personal data sent, and the difference to the built-in calendar is kept on your phone.' },
  { h: 'Notes and reminders', p: 'The notes you write, their reminder times and any shopping list you keep in Notes are kept with your other data: encrypted on your phone and, when you are signed in, in your online copy. A reminder is a notification scheduled on your phone, so it also works offline, and it shows the note\'s title on your lock screen. If you tell the Assistant to remind you, it saves the reminder in the same way.' },
  { h: 'AI answers (optional)', p: 'The Assistant answers from your own data first. For other questions you can turn on AI, and nothing is sent until you do. Online AI sends the question you type, and the language you use, over the internet through our server to an AI service (OpenRouter), which passes it to an AI model provider to write the answer. Our server only counts how many questions each account asks per day to enforce a limit. It does not save your questions or the answers, but the AI service and its model providers may handle them under their own policies, so do not type passwords, ID numbers or other secrets. You must be signed in to use it. Smart chat runs on your phone: the model is downloaded once from Hugging Face (huggingface.co), and after that the questions and answers stay on your phone and are not sent anywhere. Smart chat answers can be wrong; check important facts.' },
  { h: 'Chat in your language', p: 'Translating your messages is done on your phone with Google ML Kit. The first time you pick a language, the language pack is downloaded from Google. Your messages are not sent to Google or to us for translation.' },
  { h: 'How you feel', p: 'If you use Feeling unwell? in the Quick log, the symptom you pick or type, such as headache or tired, is kept with your habit data in the same way. The energy estimate is worked out on your phone from what you logged. They are used only to show your own record and are never used for advertising. My Life 1.0 does not diagnose or give medical advice.' },
  { h: 'Other services', p: 'To work, the app contacts these services: waktusolat.app and e-solat.gov.my for prayer times and the Hijri date (your location is sent to waktusolat.app, see Location); date.nager.at for Malaysian public holidays (no personal data is sent); and Supabase for sign-in and sync. If you use AI: openrouter.ai (through our server) for Online AI and huggingface.co to download Smart chat models. For language chat, Google downloads the language pack. In the GitHub edition, GitHub is contacted when you tap Check for updates. GitHub (raw.githubusercontent.com) is also contacted once to download the Hafazan Check model. As with any internet request, each service can see your device\'s IP address. Quran Audio streams and downloads recitations from alquran.cloud (cdn.islamic.network). Your phone contacts them when you play or save audio, and, as with any web request, they can see your IP address. We send them nothing else.' },
  { h: 'App lock', p: 'If you turn on App lock, your PIN is stored only on your phone in scrambled (hashed) form. We cannot see it or reset it for you.' },
  { h: 'Your control', p: 'You can export everything at any time from Settings (you choose which modules go in the file, including ones you turned off), reset all your data (this also erases the online copy), or delete your account in Settings, which permanently removes your account and everything saved online. If you own a family, deleting your account also deletes the family. Removing the app from your phone removes only the data on that phone.' },
  { h: 'Contact', p: 'Questions about privacy go to the developer, Adli Syahmi. Email adlisyahmi324@gmail.com or mylifeapp.support@gmail.com.' },
];
export const TERMS: Sec[] = [
  { h: 'Using My Life 1.0', p: 'My Life 1.0 is a personal organiser for your own use. Keep your phone and your PIN private. You are responsible for what is done on your device.' },
  { h: 'Your content', p: 'Everything you add belongs to you. We only store and show it back to you.' },
  { h: 'Religious content', p: 'Quran text, zikir and prayer times are provided as a convenience. Prayer times follow JAKIM and are only accurate in Malaysia. Please confirm with your local authority where it matters. Quran recitations are streamed from alquran.cloud (Islamic Network) and remain the work of their reciters.' },
  { h: 'Assistant', p: 'My Life Assistant answers from your own data and is not a financial, medical or religious adviser. If you turn on AI, its answers can be wrong or out of date, so please check important facts with an official source.' },
  { h: 'No warranty', p: 'The app is provided as is. Keep a backup using Export. We are not liable for loss of data.' },
  { h: 'Changes', p: 'These terms may change as the app grows. The latest version is always in Settings, under About.' },
];
